export function normalize(v){return String(v??'').toLowerCase().replace(/[’']/g,'').replace(/[^\p{L}\p{N}.%]+/gu,' ').trim().replace(/\s+/g,' ')}
export function evaluate(q,answer){if(q.question_type==='fill'){return (q.accepted_answers||q.correct_answer).some(a=>normalize(a)===normalize(answer))}return JSON.stringify([...(answer||[])].map(Number).sort((a,b)=>a-b))===JSON.stringify([...q.correct_answer].map(Number).sort((a,b)=>a-b))}
export function shuffle(a,rng=Math.random){let b=[...a];for(let i=b.length-1;i>0;i--){const j=Math.floor(rng()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b}
export function prepareQuestion(q){if(!q.options?.length)return {...q};const order=shuffle(q.options.map((_,i)=>i));return {...q,options:order.map(i=>q.options[i]),correct_answer:order.map((x,i)=>q.correct_answer.includes(x)?i:-1).filter(i=>i>=0),option_explanations:order.map(i=>q.option_explanations?.[i]||q.explanation)}}
export function percentage(a,b){return b?Math.round(100*a/b):0}
export function accuracy(attempts){return percentage(attempts.filter(a=>a.correct).length,attempts.length)}
export function topicStats(attempts,lessons){return lessons.map(l=>{let a=attempts.filter(x=>x.section===l.id);return {id:l.id,title:l.title,module:l.module,total:a.length,accuracy:accuracy(a),wrong:a.filter(x=>!x.correct).length}})}
export function readiness(state,lessons,modules){const a=state.attempts||[],exams=state.exams||[],coverage=percentage((state.completed||[]).length,lessons.length);if(!a.length)return {score:0,label:'Not assessed',coverage,hard:0,mock:0,evidence:0};const recent=accuracy(a.slice(-30));const hard=a.filter(x=>x.difficulty==='hard');const mocks=exams.filter(x=>x.mode==='mock');const mock=mocks.length?Math.round(mocks.slice(-3).reduce((s,e)=>s+e.score,0)/Math.min(3,mocks.length)):0;const topics=topicStats(a,lessons).filter(x=>x.total>=3);const weak=topics.length?Math.round(topics.reduce((s,x)=>s+x.accuracy,0)/topics.length):0;const conceptHistory=a.slice(-100).reduce((r,x)=>{const k=x.section+'|'+x.topic;(r[k]||=[]).push(x);return r},{});const repeated=Object.values(conceptHistory).filter(xs=>xs.filter(x=>!x.correct).length>=2&&!xs.slice(-2).every(x=>x.correct)).length;const moduleCoverage=modules.filter(m=>a.filter(x=>x.module===m.id).length>=5).length/modules.length;let score=Math.round(.25*accuracy(a)+.15*coverage+.15*recent+.15*accuracy(hard)+.2*mock+.1*weak-Math.min(10,repeated));const strongEvidence=a.length>=100&&moduleCoverage===1&&hard.length>=15&&mocks.length>=2&&modules.filter(m=>m.weight>=15).every(m=>accuracy(a.filter(x=>x.module===m.id))>=85)&&accuracy(hard)>=80&&repeated<=2;if(!strongEvidence)score=Math.min(score,89);score=Math.max(0,Math.min(100,score));return {score,label:score>=90?'Strong exam readiness':score>=80?'Almost ready':score>=70?'Needs more practice':score>=50?'Needs major revision':'Not ready',coverage,hard:accuracy(hard),mock,evidence:Math.round(moduleCoverage*100),strongEvidence}}
export function selectWeighted(bank,modules,count,weights=true){if(!weights)return shuffle(bank).slice(0,count);let result=[],left=count;modules.forEach((m,i)=>{let n=i===modules.length-1?left:Math.round(count*m.weight/100);left-=n;const pool=bank.filter(q=>q.module===m.id);result.push(...shuffle(pool).slice(0,n))});return shuffle(result)}
export function buildExam(bank,modules,count){const counts={easy:Math.round(count*.2),medium:Math.round(count*.5),hard:count-Math.round(count*.2)-Math.round(count*.5)};let result=[],remaining={...counts};for(const [mi,m]of modules.entries()){const n=mi===modules.length-1?count-result.length:Math.round(count*m.weight/100);let pool=shuffle(bank.filter(q=>q.module===m.id));for(let j=0;j<n;j++){let d=Object.keys(remaining).filter(d=>remaining[d]>0&&pool.some(q=>q.difficulty===d)).sort((a,b)=>remaining[b]-remaining[a])[0];if(!d)d=pool[0]?.difficulty;const idx=pool.findIndex(q=>q.difficulty===d);if(idx<0)break;result.push(pool.splice(idx,1)[0]);remaining[d]--}}return shuffle(result)}
export function answered(a){return typeof a==='string'?a.trim().length>0:Array.isArray(a)&&a.length>0}
export function validateProgress(v){if(!v||typeof v!=='object'||!Array.isArray(v.attempts)||!Array.isArray(v.completed)||!Array.isArray(v.exams))throw Error('Invalid progress backup');if(v.attempts.some(a=>typeof a.correct!=='boolean'||typeof a.section!=='string'))throw Error('Invalid attempt records');return v}
